const AGENTS_SNIPPET_LABEL=`[Agents]`;function projectParkedAgentHandles(e){return e.handles.filter(e=>e.phase===`parked`)}function renderAgentsSnippet(t){let n=projectParkedAgentHandles(t).map(e=>`<agent id="${escapeXml(e.identity.id)}" name="${escapeXml(e.identity.name)}">${escapeXml(e.lastStatus===``?`(no status)`:e.lastStatus)}</agent>`);return[AGENTS_SNIPPET_LABEL,`<agents>`,...n,`</agents>`].join(`
`)}function resolveAgentsAnnouncement(t){let n=t.messages.findLast(t=>t.role===`assistant`&&typeof t.content==`string`&&t.content.startsWith(AGENTS_SNIPPET_LABEL)),r=t.store??{handles:[]};if(n===void 0&&projectParkedAgentHandles(r).length===0)return;let i=renderAgentsSnippet(r);return n?.content===i?void 0:i}function escapeXml(e){return e.replaceAll(`&`,`&amp;`).replaceAll(`"`,`&quot;`).replaceAll(`<`,`&lt;`).replaceAll(`>`,`&gt;`)}export{projectParkedAgentHandles,renderAgentsSnippet,resolveAgentsAnnouncement};